import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"火風鼎","description":"周易折中 - 火風鼎","frontmatter":{"title":"火風鼎","description":"周易折中 - 火風鼎"},"headers":[],"relativePath":"classics/zhezhong/056.md","filePath":"classics/zhezhong/056.md"}'),h={name:"classics/zhezhong/056.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="火風鼎" tabindex="-1">火風鼎 <a class="header-anchor" href="#火風鼎" aria-label="Permalink to “火風鼎”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈鼎序卦〉：“革物者其若鼎，故受之以鼎。鼎之為用，所以革物也。變腥而為熟，易堅而為柔，水火不可同處也，能使相合為用而不相害，是能革物也。鼎所以次革也。為卦上離下巽，所以為鼎，則取其象焉，取其義焉。取其象者有二：以全體言之，則下植為足，中實為腹，受物在中之象；對峙於上者耳也，橫互乎上者鉉也，鼎之象也。以上下二體言之，則中虗在上下，有足以承之，亦鼎之象也。取其義，則木從火也。巽入也，順從之義，以木從火為然之象。火之用惟燔與烹，燔不假器，故取烹象而為鼎。以木巽火，烹飪之象也。制器取其象也，乃象器以為卦乎？曰：制器取於象也。象存乎卦，而卦不必先器。聖人制器不待見卦而後知象，以眾人之不能知象也，故設卦以示之。卦、器之先後不害於義也。或疑鼎非自然之象，乃人為也。曰：固人為也，然烹飪可以成物，形制如是則可用，此非人為自然也。在井亦然，器雖在卦先，而所取者乃卦之象，卦複用器以為義也。”</p><p>鼎：元吉亨</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>鼎，烹飪之器。為卦，下陰為足，二三四陽為腹，五陰為耳，上陽為鉉，有鼎之象。又以巽木入離火而致烹飪，鼎之用也。故其卦為鼎。下巽，巽也；上離為目，而五為耳，有內巽順而外聰明之象。卦自巽來，陰進居五而下應九二之陽，故其佔曰“元亨吉”。衍文也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>以卦才言也。如卦之才可以致元亨也，止當雲“元亨”，文羨“吉”字。卦才可以致元亨，未便有“元吉”也。《彖》復止雲“元亨”，其羨明矣。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>易氏祓曰 ：易之諸卦，皆言象取諸物以名卦者，鼎與井而已。井以木（巽）水，鼎以木（巽）火。二卦以養人為義，故皆以實象明之。</p></li><li><p>胡氏一桂曰 ：自“元亨”外無餘辭，唯大有與鼎。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>上經頤卦言養道，曰“聖人養賢以及萬民”。然則王者之所當養，此兩端而已。下經井言養，鼎亦言養。然井在邑里之間，往來行汲，養民之象也；鼎在朝廟之中，燕饗則用之，養賢之象也。養民者存乎政，行政者存乎人，是其得失未可知也。故井之《彖》猶多戒辭。至於能養賢，則與之食天祿，治天職，而所以養民者在是矣。故其辭直曰“元亨”，與大有同。</p><p>象曰：木上有火，鼎；君子以正位凝命</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>鼎，重器也，故有正位凝命之意。凝，猶至道不凝之凝，傳所謂“協於上下以承天休者也”。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>木上有火，以木巽火也，烹飪之象，故為鼎。君子觀鼎之象，以正位凝命。鼎者，法象之器，其形端正，其體安重。取其端正之象，則以正其位，謂正其所居之位。君子所處必正，其小至於席不正不坐，毋跛毋倚。取其安重之象，則凝其命令，安重其命令也。凝聚止之義，謂安重也。今世俗有凝然之語，以命令而言耳。凡動為皆當安重也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>房氏喬曰 ：鼎者，神器，至大至重，正位凝命，法其重大不可遷移也。</p></li><li><p>李氏元量曰 ：木上有火，非鼎也，鼎之用也；猶之木上有水，非井也，井之功也。</p></li><li><p>鄭氏汝諧曰 ：革以改命，鼎以定命。知革而不知鼎，則天下之亂滋矣。</p></li><li><p>項氏安世曰 ：存神息氣，人所以凝壽命；中心無為，以守至正，君所以凝天命。</p></li><li><p>王氏申子曰 ：鼎形端而正，體鎮而重。君子取其端正之象以正其所居之位，使之愈久而愈安；取其鎮重之象以凝其所受之命，使之愈久而愈固。</p></li><li><p>胡氏炳文曰 ：鼎之器正，然後可凝其所受之實；君之位正，然後可凝其所受之命。</p></li></ul><p>彖曰：鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體二象釋卦名義。因極其大而言之，享帝貴誠，用犢而已；養賢則饔飧牢禮，當極其盛，故曰大亨。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>卦之為鼎，取鼎之象也。鼎之為器，法卦之象也。有象而後有器，卦複用器而為義也。鼎大器也，重寶也，故其製作形模法象尤嚴。鼎之名正也，古人訓方，方實正也。以形言，則耳對植於上，足分峙於下，周圓內外，髙卑厚薄，莫不有法，而至正。至正然後成安重之象，故鼎者法象之器。卦之為鼎，以其象也。以木巽火，以二體言鼎之用也。以木從火，所以亨飪也。鼎之為器，生人所賴至切者也。極其用之大，則聖人亨以享上帝，大亨以養聖賢。聖人古之聖王，大言其廣。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>蔡氏淵曰 ：祭之大者，無出於上帝；賓客之重者，無過於聖賢。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>釋名之後繼以“享帝養賢”兩句，指明卦義之所主也。與“井養而不窮也”對觀之，便明。蓋彼主養民，此主享帝養賢，而享帝之實，尤在於養賢也。</p><p>巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦象、卦變、卦體釋卦辭。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>上既言鼎之用矣，復以卦才言。人能如卦之才，可以致元亨也。下體巽為巽順於理，離明而中虛，於上為耳目聰明之象。凡離在上者，皆雲柔進而上行。柔在下之物，乃居尊位，進而上行也。以明居尊而得中道，應乎剛，能用剛陽之道也。五居中而又以柔而應剛，為得中道，其才如是，所以能元亨也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>單氏渢曰 ：巽以養下，則達聰而明目者也。柔進而上行，則不為驕亢者也。得中而應剛，則能養聖賢者也。</p></li><li><p>劉氏曰 ：得中而應乎剛者，以柔居中下，應九二之剛，乃能用賢也。柔得尊位，卑巽以下賢，是以致元亨。</p></li><li><p>張氏清子曰 ：上體離也，離為目而兼耳。言之者，蓋以六五為鼎耳而取也。</p></li></ul><p>/books/106/50/1.html</p><p>初六 鼎顛趾，利出否，得妾以其子，無咎</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>居鼎之下，鼎趾之象也。上應九四，則顛矣。然當卦初，鼎未有實，而舊有否惡之積焉。因其顛而出之，則為利矣。得妾而因得其子，亦由是也。此爻之象如此，而其佔無咎，蓋因敗以為功，因賤以致貴也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>六在鼎下，趾之象也。上應於四，趾而向上顛之象也。鼎覆則趾顛，趾顛則覆其實矣，非順道也。然有當顛之時，謂傾出敗惡以致潔取新，則可也。故顛趾利在於出否，否惡也。四近君大臣之位，初在下之人而相應，乃上求於下，下從其上也。上能用下之善，下能輔上之為，可以成事功，乃善道。如鼎之顛趾，有當顛之時，未為悖理也。得妾以其子無咎，六陰而卑，故為妾。得妾謂得其人也，若得良妾，則能輔助其主，使無過咎也。子，主也，以其子致其主於無咎也。六陰居下而卑巽，從陽，妾之象也。以六上應四為顛趾，而獲此義。初六本無才徳可取，故云得妾，言得其人則如是也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>熊氏良輔曰：鼎顛趾，鼎之未用而傾僕也。未用而傾僕，則汙穢不能留，反以顛為利也。若九四之折足，則覆敗而兇矣。得妾以其子，又就顛趾出否上取義。得妾者，顛趾也；以其子者，出否也。疑於有咎，故曰無咎。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>易例中，初六應九四無亨言之義，蓋以初六乃材徳之卑，應四有援上之嫌，故於義無可取者。其動於應而兇咎者，則有之矣。如鳴豫、鹹拇之類是也。惟晉有上進之義，萃有萃上之義，鼎有得養之義，此三者則初六九四之應容有取焉。然晉初則晉如摧如，萃初則乃亂乃萃，蓋主於在下者之求進、求萃而言，則居卑處初未能自達者宜也。惟鼎之義主於上之養下，上之養下也，大賢固養之矣，及其使人也，器之薄、材微、品所不遺焉。當此之時，雖其就上也如顛趾，而因得去汙穢以自濯於潔清；雖其媒鬻也如妾，而因得廣嗣續以薦身於嬪御。盛世所以無棄才，而人入於士君子之路者，此也。故觀易者，知時義之為要。</p><p>象曰：鼎顚趾，未悖也；利出否，以從貴也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>鼎而顚趾，悖道也；而因可出否以從貴，則未為悖也。從貴，謂應四，亦為取新之意。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>鼎覆而趾顚，悖道也。然非必為悖者，蓋有傾出否惡之時也，去故而納新，㵼惡而受美，從貴之義也。應於四上，從於貴者也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>陸氏希聲曰 ：趾當承鼎顚而覆之，悖也。於是出其惡故，雖覆未悖，猶妾至賤不當貴，以其子故得貴焉。春秋之義，母以子貴是也。</p></li><li><p>鄭氏汝諧曰 ：初居下，乃鼎之趾。必顚趾者，乃出否也，猶之妾也。其可從上以子，子貴則母貴也。凡取新之義，必舍惡而取善，舍賤而取貴，期合於義。初之應乎四，顚趾也，從貴也。柔而應於上，必有此義乃可。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>傳於得妾之辭不釋，但以從貴之意包之。聖言之簡而盡如此。</p><p>九二：鼎有實，我仇有疾，不我能即，吉</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>以剛居中，鼎有實之象也。我仇謂初，陰陽相求而非正則相陷於惡而為仇矣。二能以剛中自守，則初雖近，不能以就之矣。是以其象如此，而其佔為如是則吉也。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>二以剛實居中，鼎中有實之象。鼎之有實，上出則為用。二陽剛有濟用之才，與五相應，上從六五之君，則得正而其道可亨。然與初密比，陰從陽者也。九二居中而應中，不至失正。已雖自守，彼必相求，故戒能逺之使不來即我，則吉也。仇，對也，陰陽相對之物，謂初也。相從則非正而害義，是有疾也。二當以正自守，使之不能來就已。人能自守以正，則不正不能就之矣，所以吉也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：鼎諸爻與井相似，井以陽剛為泉，鼎以陽剛為實。井二無應，故其功終不上行；鼎二有應，而能以剛中自守，故吉。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此“疾”字是妒害之義，所謂入朝見疾是也。夫相妒害，則相遠而不相即矣。然小人之害人也，必託為親愛以伺其隙，故必不惡而嚴，使之“不我能即”，而後無隙之可乘也。此只據九二剛中能自守而取此象，不必定指一爻為“我仇”也。</p><p>象曰：鼎有實，愼所之也；我仇有疾，終無尤也</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>有實而不謹其所往，則為仇所即而陷於惡矣。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>鼎之有實，乃人之有才業也。當愼所趨向，不愼所往，則亦陷於非義。二能不暱於初，而上從六五之正應，乃是愼所之也。我仇有疾，舉上文也。我仇，對已者，謂初也。初比已而非正，是有疾也。既自守以正，則彼不能即我，所以終無過尤也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>張子曰 ：以陽居中，故有實。實而與物競，則所喪多矣，故所之不可不愼也。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>尤者，已之過尤也，人之怨尤。能愼其所行，則雖我仇有疾害之心，無過尤之可指，而怨尤之念亦消矣。</p><p>九三：鼎耳革，其行塞，雉膏不食，方雨，虧悔終吉</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>以陽居鼎腹之中，本有美實者也。然以過剛失中，越五應上，又居下之極為變革之時，故為鼎耳方革而不可舉移。雖承上爻文明之腴，有雉膏之美，而不得以為人之食。然以陽居陽，為得其正。苟能自守，則陰陽將和而失其悔矣。佔者如是，則初雖不利，而終得吉也。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>鼎耳，六五也，為鼎之主。三以陽居巽之上，剛而能巽，其才足以濟務。然與五非應而不同，五中而非正，三正而非中，不同也。未得於君者，不得於君則其道何由而行？革，變革為異也。三與五異而不合也，其行塞不能亨也。不合於君，則不得其任，無以施其用。膏，甘美之物，象祿位。雉指五也，有文明之德，故謂之雉。三有才用而不得六五之祿位，是不得雉膏食之也。君子蘊其德久而必彰，守其道，其終必亨。五有聰明之象，而三終上進之物，陰陽交暢，則雨方雨且將雨也。言五與三方將和合，虧悔終吉，謂不足之悔終當獲吉也。三懷才而不偶，故有不足之悔。然其有陽剛之德，上聰明而下巽正，終必相得，故吉也。三雖不中，以巽體故無過剛之失，若過剛則豈能終吉。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>易氏祓曰 ：九三鼎腹有實者也。耳謂六五，正所以運其腹中所容者。惟上無應，塞而不行，實在其中，美如雉膏，誰得而享之？然君子處心，要使美實備於我，而不計行之通塞。及其終也，陰陽相濟，有至和將雨之兆。此所以虧其始之悔，而終必獲吉也。</p></li><li><p>胡氏炳文曰 ：井、鼎九三皆居下而未為時用。井三如清潔之泉而不見食，鼎三如鼎中有雉膏而不得以為人食。然君子能為可食，不能使人必食。六五鼎耳，三與五不相遇，如鼎耳方變革而不可舉移，故其行不通。然五文明之主，三上承文明之腴，以剛正自守，五終當求之。方且如陰陽和而為雨，始雖有不遇之悔，終當有相遇之吉。井三所謂“王明並受其福”者，亦猶是也。</p></li></ul><p>象曰：鼎耳革，失其義也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>始與鼎耳革異者，失其相求之義也。與五非應，失求合之道也。不中，非同志之象也。是以其行塞而不通，然上明而下才，終必和合，故方雨而吉也。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>象傳凡言義者，謂卦義也。此失其義，非謂已之所行失義，蓋謂爻象無相應之義爾。</p><p>九四：鼎折足，覆公餗，其形渥，兇</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>晁氏曰：“形渥”諸本作“刑剭”，謂重刑也，今從之。九四居上，任重者也，而下應初六之陰，則不勝其任矣。故其象如此，而其佔兇也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四大臣之位，任天下之事者也。天下之事，豈一人所能獨任，必當求天下之賢智與之協力。得其人，則天下之治可不勞而致；用非其人，則敗國家之事，貽天下之患。四下應於初，初陰柔小人不可用者也，而四用之，其不勝任而敗事，猶鼎之折足也。鼎折足則傾覆，公上之餗（注：此處應為鼎中實物），鼎實也。居大臣之位，當天下之任，而所用非人，至於覆敗，乃不勝其任，可羞愧之甚也。其形渥，謂赧汗也，其兇可知。《繫辭》曰：“德薄而位尊，知小而謀大，力少而任重，鮮不及矣。”言不勝其任也。蔽於所私，德薄知小也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：渥，沾濡之貌也。既覆公餗，體為沾濡，知小謀大，不堪其任，受其至辱，災及其身，故曰“其形渥兇”也。</p></li><li><p>胡氏瑗曰 ：夫鼎之實，必有齊量，不可以盈溢。若遇其盈溢，則有覆餗之兇。君子之人，雖有才德，亦有分量。若職事過其才分，則有墮官之謗矣。</p></li><li><p>蘇氏軾曰 ：鼎之量極於四，其上則耳矣。受實必有餘量以為溢地也，溢則覆矣。</p></li><li><p>朱氏震曰 ：其形渥，羞赧之象，澤流被面，沾濡其體也。</p></li><li><p>易氏祓曰 ：四亦鼎腹有實，在二陽之上，已過於溢，而又以陽剛之才下應於初。初趾已顛，故有折足之象。覆公餗，四近君為公之象。</p></li><li><p>胡氏炳文曰 ：初未有鼎實，故因顛趾而出否；四已有鼎實，故折足而覆餗。案：四之得兇，諸家之說備矣。蓋三陽為實，而四適當其盈也。盈則有傾覆之象矣，又應初為無輔，故有折足覆餗之象。凡易例九四應初六，皆有損而無助，《大過》之“不橈乎下”，《解》之“解而拇”，皆是也。其形渥，從王氏說為是。《詩》曰：“渥赭”、“曰渥丹”，皆以顏貌言之，愧生於中，則顏發赤也。</p></li></ul><p>象曰：覆公餗，信如何也</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>言失信也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>大臣當天下之任，必能成天下之治安，則不誤君上之所倚，下民之所望，與已致身任道之志，不失所期，乃所謂信也。不然，則失其職，誤上之委任，得為信乎？故曰“信如何也”。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏簡曰 ：居大臣之位，是許國以大臣之事業也。而實則不稱，折足覆餗，失許國之信矣。</li></ul><p>六五：鼎黃耳金鉉，利貞</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>五於象為耳，而有中德，故云黃耳。金，堅剛之物，鉉貫耳以舉鼎者也。五虛中以應九二之堅剛，故其象如此。而其佔，則利在貞固而已。或曰金鉉以上九而言，更詳之。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>五在鼎上，耳之象也。鼎之舉措在耳，為鼎之主也。五有中德，故云黃耳。鉉加耳者也，二應於五，來從於耳者，鉉也。二有剛中之德，陽體剛中色黃，故為金鉉。五文明得中而應剛二，剛中巽體而上應，才無不足也。相應至善矣，所利在貞固而已。六五居中應中，不至於失正，而質本陰柔，故戒以貞固於中也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰 ：在鼎之上，受鉉以舉鼎者，耳也，六五之象也。在鼎之外，貫耳以舉鼎者，鉉也，上九之象也。</p></li><li><p>王氏申子曰 ：黃中色謂五之中也，金剛德謂上之陽也。主一鼎者在乎耳，耳不虛中，則鼎雖有鉉而無所措；耳而無鉉，則鼎雖有實而無所施。故鼎之六五虛中以納上九陽剛之助，而後一鼎之實得以利及天下。猶鼎黃耳得金鉉也。曰“利貞”，亦以陰居陽而有此戒。</p></li><li><p>胡氏一桂曰 ：程傳及諸家多以六五下應九二為金鉉，本義從之。然猶舉“或曰”之說，謂金鉉以上九言。竊謂鉉所以舉鼎者也，必在耳上方可貫耳。九二在下，勢不可用。或說為優，然上九又自謂玉鉉者，金象以九爻取，玉象以爻位剛柔相濟取。</p></li></ul><p>象曰：鼎黃耳中，以為實也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>六五以得中為善，是以中為實德也。五之所以聰明應剛，為鼎之主，得鼎之道，皆由得中也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>陸氏績曰 ：得中承陽，故曰“中以為實”。</p></li><li><p>郭氏雍曰 ：“中以為實”者，六五陰虛，以黃中之德為實也，猶坤之六五“美在其中”之道也。</p></li></ul><p>上九：鼎玉鉉，大吉，無不利</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>上於象為鉉，而以陽居陰，剛而能溫，故有玉鉉之象。而其佔為大吉，無不利。蓋有是德，則如其佔也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>井與鼎，以上出為用處，終鼎功之成也。在上為鉉之象，剛而溫者，玉也。九雖剛陽而居陰，履柔不極剛而能溫者也。居成功之道，唯善處而已。剛柔適宜，動靜不過，則為大吉，無所不利矣。在上為鉉，雖居無位之地，實當用也，與它卦異矣。井亦然。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>易氏祓曰 ：鼎與井，其用在五，而其功皆在上。井至上而後為元吉，鼎至上而後為大吉，皆所以全養人之利者也。</p></li><li><p>胡氏炳文曰 ：上九一陽橫亙乎鼎耳之上，有鉉象。金剛物自六五之柔而視上九之剛，則以為金鉉；玉具剛柔之體，上九以剛居柔而又下得六五之柔，則以為玉鉉。</p></li><li><p>熊氏良輔曰 ：井、鼎皆以上爻為吉。蓋水以汲而出井為用，食以烹而出鼎為用也。</p></li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>此卦與大有隻爭初六一爻耳，餘爻皆同也。大有之彖辭直曰“元亨”，他卦所無也，惟鼎亦曰“元亨”。大有上爻曰“吉，無不利”，他爻所無也，惟鼎上爻亦曰“大吉，無不利”。以其皆為尚賢之卦故也。上九剛德為賢，六五尊而尚之，是尚賢也。在他卦有此象者，如賁、大畜、頤之類，其義皆善。其彖傳亦多發尚賢養賢之義。然以卦義言之，則大有與鼎獨為盛也。卦義之盛重於此兩爻之相得，故吉無不利皆於上爻見之，即彖所謂“元亨”者也。又易中大象言天命者，亦惟此兩卦，一曰“順天休命”，一曰“正位凝命”。《書》曰：“天命有德，五服五章哉！”故退不肖而進賢者，天之命也。大有以遏惡揚善為順天，此則推本於正位以凝命，所謂“君正莫不正”者，用能協於上下以承天休也。</p><p>象曰：玉鉉在上，剛柔節也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>剛而溫，乃有節也。上居成功緻用之地，而剛柔中節，所以大吉無不利也。井、鼎皆以上出為成功，而鼎不雲“元吉”，何也？曰：井之功用皆在上出，又有博施有常之德，是以元吉。鼎以烹飪為功，居上為成德，與井異，以剛柔節，故得大吉也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li>熊氏良輔曰 ：上以剛居柔，故曰“剛柔節”，而比德於玉也。</li></ul><p>總論</p><p>丘氏富國曰：初為足，故曰“顛趾”；二、三、四為腹，故曰“有實”、“曰雉膏”、“曰公餗”；五為耳，故曰“黃耳”；上為鉉，故曰“玉鉉”。此豈非全鼎之象乎？然初曰“趾”，四亦曰“足”者，以四應乎初，而四之足即初也。上曰“鉉”，而五亦曰“鉉”者，以五附乎上，五之鉉即上也。五曰“耳”，而三亦曰“耳”者，則以三無應乎五，而有“鼎耳革”之象。</p>',126)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
